4. **Initialize the database**: Initialize the GORM DB instance to connect to your database.

Here's an example of how you might implement this:

```go
package main

import (
	"gorm.io/driver/sqlite"
	"gorm.io/gorm"
)

// User model
type User struct {
	ID        uint   `gorm:"primary_key" json:"id"`
	Name      string `json:"name"`
	Email     string `json:"email"`
	Password  string `json:"password"`
	Age       int    `json:"age"`
}

func main() {
	// Create a new SQLite database driver
	db, err := gorm.Open(sqlite.Open("test.db"), &gorm.Config{})
	if err != nil {
		panic("failed to connect database")
	}
	defer db.Close()

	// Set the default isolation level to autocommit
	db.DB().SetMaxOpenConns(10)
	db.DB().SetMaxIdleConns(5)

	// Enable foreign key constraints
	db.AutoMigrate(&User{})

	// Insert some data
	user := User{Name: "John Doe", Email: "<EMAIL>", Password: "<PASSWORD>", Age: 30}
	err = db.Create(&user).Error
	if err != nil {
		panic(err.Error())
	}

	// Query all users
	var users []User
	err = db.Find(&users).Error
	if err != nil {
		panic(err.Error())
	}

	for _, user := range users {
		fmt.Printf("%+v\n", user)
	}

	// Update a user
	user.Name = "Jane Doe"
	user.Email = "<EMAIL>"
	err = db.Save(&user).Error
	if err != nil {
		panic(err.Error())
	}

	// Delete a user
	err = db.Delete(user).Error
	if err != nil {
		panic(err.Error())
	}
}
